sys_script_include.script:
var IncentNowClientUtils = Class.create();
IncentNowClientUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


    getPlansForUser: function(userSysId, fiscalYearSysId, fiscalPeriodSysId) {
        if (!userSysId || !fiscalYearSysId || !fiscalPeriodSysId)
            return 'sys_idISEMPTY';

        var participantGR = new GlideRecordSecure('x_ctans_incentnow_participant_assignment');
        participantGR.addQuery('user', userSysId);
        participantGR.addQuery('fiscal_year', fiscalYearSysId);
        participantGR.addQuery('status', 'active');
        participantGR.setLimit(2);
        participantGR.query();

        if (!participantGR.next())
            return 'sys_idISEMPTY';

        var participantAssignmentSysId = participantGR.getUniqueValue();

        if (participantGR.next())
            return 'sys_idISEMPTY';

        var planIds = [];
        var assignmentGR = new GlideRecordSecure('x_ctans_incentnow_plan_users');
        assignmentGR.addQuery('participant_assignment', participantAssignmentSysId);

        var periodCondition = assignmentGR.addNullQuery('fiscal_period');
        periodCondition.addOrCondition('fiscal_period', fiscalPeriodSysId);

        assignmentGR.addQuery('x_ctans_incentnow_plan.fiscal_year', fiscalYearSysId);
        assignmentGR.addQuery('x_ctans_incentnow_plan.status', 'active');
        assignmentGR.query();

        while (assignmentGR.next()) {
            var planSysId = assignmentGR.getValue('x_ctans_incentnow_plan');
            if (planSysId && planIds.indexOf(planSysId) == -1)
                planIds.push(planSysId);
        }

        return planIds.length ? 'sys_idIN' + planIds.join(',') : 'sys_idISEMPTY';
    },

    getPlan: function() {
        var userSysId = this.getParameter('sysparm_user');
        var fiscalYearSysId = this.getParameter('sysparm_fiscal_year');
        var fiscalPeriodSysId = this.getParameter('sysparm_fiscal_period');

        var qualifier = this.getPlansForUser(userSysId, fiscalYearSysId, fiscalPeriodSysId);

        if (!qualifier || qualifier == 'sys_idISEMPTY')
            return '';

        var planIds = [];
        var planGR = new GlideRecordSecure('x_ctans_incentnow_plan');
        planGR.addEncodedQuery(qualifier);
        planGR.query();

        while (planGR.next())
            planIds.push(planGR.getUniqueValue());

        return planIds.join(',');
    },

    getFiscalDates: function() {

        var fiscalYear = parseInt(this.getParameter('sysparm_fiscalYear'), 10);
        var startMonth = parseInt(this.getParameter('sysparm_fiscalStartMonth'), 10);

        if (!fiscalYear || !startMonth || startMonth < 1 || startMonth > 12) {
            return '';
        }

        /* ---------------- Start Date ---------------- */
        var startGDT = new GlideDateTime();
        startGDT.setDisplayValueInternal(
            fiscalYear + '-' + this._pad(startMonth) + '-01 00:00:00'
        );

        /* ---------------- End Month & Year (12 months) ---------------- */
        var endMonthIndex = startMonth + 11;
        var endYear = fiscalYear + Math.floor((endMonthIndex - 1) / 12);
        var endMonth = ((endMonthIndex - 1) % 12) + 1;

        /* ---------------- End Date (last day of end month) ---------------- */
        var endGDT = new GlideDateTime();
        endGDT.setDisplayValueInternal(
            endYear + '-' + this._pad(endMonth) + '-01 00:00:00'
        );
        endGDT.addMonthsUTC(1);
        endGDT.addDaysUTC(-1);

        return JSON.stringify({
            start_date: startGDT.getLocalDate().toString(),
            end_date: endGDT.getLocalDate().toString(),
            fiscal_end: endMonth // numeric choice value (1–12)
        });
    },

    getFiscalDatesbyServer: function(fiscalYear, startMonth) {

        if (!fiscalYear || !startMonth || startMonth < 1 || startMonth > 12) {
            return '';
        }

        /* ---------------- Start Date ---------------- */
        var startGDT = new GlideDateTime();
        startGDT.setDisplayValueInternal(
            fiscalYear + '-' + this._pad(startMonth) + '-01 00:00:00'
        );

        /* ---------------- End Month & Year (12 months) ---------------- */
        var endMonthIndex = startMonth + 11;
        var endYear = fiscalYear + Math.floor((endMonthIndex - 1) / 12);
        var endMonth = ((endMonthIndex - 1) % 12) + 1;

        /* ---------------- End Date (last day of end month) ---------------- */
        var endGDT = new GlideDateTime();
        endGDT.setDisplayValueInternal(
            endYear + '-' + this._pad(endMonth) + '-01 00:00:00'
        );
        endGDT.addMonthsUTC(1);
        endGDT.addDaysUTC(-1);

        return JSON.stringify({
            start_date: startGDT.getLocalDate().toString(),
            end_date: endGDT.getLocalDate().toString(),
            fiscal_end: endMonth // numeric choice value (1–12)
        });
    },

    _pad: function(n) {
        return (n < 10 ? '0' : '') + n;
    },

    getInputsForDecisionTable: function() {

        var decisionTableId = this.getParameter('sysparm_decision_table');
        if (!decisionTableId)
            return '';

        var inputs = [];
        var di = new GlideRecordSecure('sys_decision_input');
        di.addQuery('model', decisionTableId);
        di.query();

        while (di.next()) {
            inputs.push(di.getUniqueValue());
        }

        // Glide List expects comma-separated sys_ids
        return inputs.join(',');
    },

    getOutputsForDecisionTable: function() {

        var decisionTableId = this.getParameter('sysparm_decision_table');
        if (!decisionTableId)
            return '';

        var outputs = [];
        var di = new GlideRecordSecure('sys_decision_multi_result_element');
        di.addEncodedQuery('nameLIKE' + GlideStringUtil.escapeQueryTermSeparator(decisionTableId), true);
        di.query();

        while (di.next()) {
            outputs.push(di.getUniqueValue());
        }

        return outputs.join(',');
    },

    getPlanFlowData: function(planGR) {
        var result = {
            hasFlows: false,
            hasMultipleFlows: false,
            flowId: "",
            flowIds: [],
            flowNames: [],
            flows: [],
            flowQuery: ""
        };

        if (!planGR || !planGR.isValidRecord())
            return result;

        var flowContextGR = new GlideRecordSecure("sys_flow_context");
        flowContextGR.addQuery("source_table", planGR.getRecordClassName());
        flowContextGR.addQuery("source_record", planGR.getUniqueValue());
        flowContextGR.orderByDesc("sys_created_on");
        flowContextGR.query();

        while (flowContextGR.next()) {
            result.hasFlows = true;

            var flowSysId = flowContextGR.getUniqueValue();

            result.flowIds.push(flowSysId);
            result.flowNames.push(flowContextGR.name.toString());

            // Detailed object (best for UI)
            result.flows.push({
                id: flowSysId,
                name: flowContextGR.name.toString(),
                state: flowContextGR.state.toString(),
                started: flowContextGR.sys_created_on.toString(),
                ended: flowContextGR.sys_updated_on.toString()
            });
        }

        // Flags
        if (result.flowIds.length === 1) {
            result.flowId = result.flowIds[0];
        }

        if (result.flowIds.length > 1) {
            result.hasMultipleFlows = true;
        }

        result.flowQuery = flowContextGR.getEncodedQuery();

        return result;
    },

    getPlanFlowDataAjax: function() {

        var sysId = this.getParameter('sysparm_sys_id');
        var table = this.getParameter('sysparm_table');

        var planFlow = new GlideRecordSecure(table);
        if (!planFlow.get(sysId))
            return JSON.stringify({
                hasFlows: false
            });

        var data = this.getPlanFlowData(planFlow);

        return JSON.stringify(data);
    },

    getUserID: function() {

        var userSysId = this.getParameter('sysparm_user_sys_id');

        if (gs.nil(userSysId))
            return '';

        var userGR = new GlideRecordSecure('sys_user');
        if (userGR.get(userSysId))
            return userGR.getValue('user_name');

        return '';

    },

    isSalesTerritoryExtensionActive: function() {
        return new IncentNowUtils().isTerritoryExtensionActive() ? 'true' : 'false';
    },

    validateBusinessUnitCompany: function() {

        var companyId = this.getParameter('sysparm_company_id');
        var businessUnitId = this.getParameter('sysparm_business_unit_id');

        var response = {
            valid: true,
            message: '',
            business_unit_company: ''
        };

        if (!businessUnitId)
            return JSON.stringify(response);

        var buGR = new GlideRecordSecure('business_unit');
        if (buGR.get(businessUnitId))
            response.business_unit_company = buGR.getValue('company');

        if (companyId && response.business_unit_company &&
            companyId != response.business_unit_company) {
            response.valid = false;
            response.message = 'Selected Company does not match with Business Unit company.';
        }

        return JSON.stringify(response);
    },

    getPlanAssignmentDetails: function() {
        var planAssignmentId = this.getParameter('sysparm_plan_assignment');
        var result = {
            success: false,
            participant_assignment: '',
            user: ''
        };

        if (!planAssignmentId) {
            return JSON.stringify(result);
        }

        var planGR = new GlideRecordSecure('x_ctans_incentnow_plan_users');
        if (!planGR.get(planAssignmentId)) {
            return JSON.stringify(result);
        }

        result.success = true;
        result.participant_assignment = planGR.getValue('participant_assignment') || '';
        result.user = planGR.getValue('x_ctans_incentnow_sales_user') || '';

        return JSON.stringify(result);
    },



    type: 'IncentNowClientUtils'
});
